<script setup>
import { computed, onMounted, onBeforeUnmount, ref } from 'vue'
import { listArticles, categoryLabel } from '../services/blog'
import { daysSince, daysUntilNext, yearsSince } from '../utils/milestones'
const articles = ref([]), query = ref(''), error = ref(''), loading = ref(true), now = ref(new Date())
const wedding = ref('2022-09-30'), editing = ref(false), draft = ref(''), notice = ref('')
const date = computed(() => new Date(`${wedding.value}T00:00:00`))
const days = computed(() => daysSince(date.value, now.value))
const years = computed(() => yearsSince(date.value, now.value))
const countdown = computed(() => daysUntilNext(date.value.getMonth(), date.value.getDate(), now.value))
const filtered = computed(() => articles.value.filter(a => a.title.toLowerCase().includes(query.value.toLowerCase())).slice(0, 5))
const today = computed(() => new Intl.DateTimeFormat('zh-CN', { month: 'long', day: 'numeric', weekday: 'long' }).format(now.value))
let timer
function save() {
 if (!/^\d{4}-\d{2}-\d{2}$/.test(draft.value) || Number.isNaN(new Date(`${draft.value}T00:00:00`).getTime()) || draft.value > new Intl.DateTimeFormat('sv-SE').format(now.value)) { notice.value = '请选择有效的结婚日期，不能晚于今天'; return }
 try { localStorage.setItem('personal-wedding-date', draft.value); wedding.value = draft.value; editing.value = false; notice.value = '' } catch { notice.value = '保存失败，请检查浏览器存储权限' }
}
onMounted(async () => {
 try { const stored = localStorage.getItem('personal-wedding-date'); if (stored && /^\d{4}-\d{2}-\d{2}$/.test(stored) && !Number.isNaN(new Date(`${stored}T00:00:00`).getTime())) wedding.value = stored } catch {}
 timer = setInterval(() => now.value = new Date(), 60000)
 try { articles.value = await listArticles({ admin: true }) } catch (e) { error.value = e.message || '文章加载失败' } finally { loading.value = false }
})
onBeforeUnmount(() => clearInterval(timer))
</script>

<template>
 <div class="personal-desk">
  <header class="desk-nav"><RouterLink to="/" class="desk-logo">d<span>.</span><small>我的个人空间</small></RouterLink><nav><RouterLink to="/" class="selected">工作台</RouterLink><RouterLink to="/admin/articles">文章</RouterLink><RouterLink to="/gallery">相册</RouterLink><RouterLink to="/admin/vault">收藏</RouterLink></nav><RouterLink to="/blog" class="desk-public">访问博客 ↗</RouterLink></header>
  <main class="desk-main">
   <div class="desk-heading"><div><p class="desk-eyebrow">MY PERSONAL DASHBOARD</p><h1>把生活和灵感，安放在这里<span>✳</span></h1><p>你好，Daixiaoming。今天也留一点时间，给热爱的事情。</p></div><span class="desk-date">{{ today }}</span></div>
   <section class="desk-grid">
    <article class="desk-card desk-intro"><span class="desk-tag">生活 · 代码 · 记录</span><h2>Hi, I'm<br>Daixiaoming<span>↗</span></h2><p>写代码，也记录生活。<br>这里是我的数字花园，和日常的小小控制中心。</p><RouterLink to="/admin/editor" class="desk-primary">＋ 写一篇新文章</RouterLink><div class="desk-intro-foot"><span class="desk-dot"></span>保持好奇，持续生长 <span>✺</span></div></article>
    <article class="desk-card desk-love"><div class="desk-card-top"><span>♡ 我们的纪念日</span><button @click="editing = !editing; draft = wedding; notice = ''">{{ editing ? '收起' : '修改日期 ↗' }}</button></div><template v-if="!editing"><div class="desk-heart">♡</div><p>一起走过的每一天，都值得纪念</p><div class="desk-days">{{ days.toLocaleString() }}<small>天</small></div><p>结婚 {{ years }} 周年 · {{ wedding.replaceAll('-', '.') }}</p><div class="desk-love-footer"><span>{{ countdown === 0 ? '今天是我们的结婚纪念日 ♡' : '距离下一个结婚纪念日' }}</span><strong>{{ countdown === 0 ? '纪念日快乐' : `${countdown} 天` }}</strong></div></template><form v-else class="desk-date-form" @submit.prevent="save"><label for="wedding">我们的结婚日期</label><input id="wedding" v-model="draft" type="date" required><p>日期保存在当前浏览器，用来计算相伴天数与纪念日倒计时。</p><button class="desk-primary">保存日期</button><p role="alert">{{ notice }}</p></form></article>
    <article class="desk-card desk-stats"><span class="desk-eyebrow">CONTENT OVERVIEW</span><h3>一点一滴，都是积累。</h3><strong>{{ loading ? '…' : articles.length }}<small>篇文章</small></strong><p>把遇到的问题，变成下一次的答案。</p><RouterLink to="/admin/articles">管理我的文章 ↗</RouterLink></article>
    <article class="desk-card desk-articles"><div class="desk-card-top"><h3>最近的记录 <small>RECENT NOTES</small></h3><RouterLink to="/admin/articles">全部文章 ↗</RouterLink></div><input v-model="query" class="desk-search" placeholder="搜索你的文章…" aria-label="搜索文章"><p v-if="loading">正在加载记录…</p><p v-else-if="error" role="alert">{{ error }}</p><p v-else-if="!filtered.length">{{ query ? '没有找到匹配的文章' : '还没有文章，开始写下第一篇吧。' }}</p><RouterLink v-for="item in filtered" :key="item.id" :to="`/admin/editor/${encodeURIComponent(item.id)}`" class="desk-article"><span><small>{{ categoryLabel(item.type) }}</small>{{ item.title }}</span><span>编辑 ↗</span></RouterLink></article>
    <article class="desk-card desk-shortcuts"><span class="desk-eyebrow">QUICK ACCESS</span><h3>常用入口</h3><RouterLink to="/admin/vault"><b>⌘</b><span>常用链接<small>收藏工具与网站</small></span>↗</RouterLink><RouterLink to="/gallery"><b>▧</b><span>我的相册<small>收藏生活的切片</small></span>↗</RouterLink><RouterLink to="/story"><b>♡</b><span>我们的故事<small>生活里的温柔时刻</small></span>↗</RouterLink></article>
   </section><footer class="desk-footer">Daixiaoming 的个人工作台 <span>慢慢记录，好好生活。 © {{ now.getFullYear() }}</span></footer>
  </main>
 </div>
</template>

